def maximumRemovals(s: str, p: str, removable: list[int]) -> int:
    def is_subseq(k):
        removed = set(removable[:k])
        j = 0
        for i, ch in enumerate(s):
            if i not in removed and ch == p[j]:
                j += 1
                if j == len(p): return True
        return False
    lo, hi = 0, len(removable)
    ans = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        if is_subseq(mid):
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return ans

